simplify_path.brute:
parts = empty list
for each part in path split on "/":
    if part is not "" and not ".": append part to parts
changed = true
while changed:   (rescan from the start after every deletion)
    changed = false
    for each index i in parts:
        if parts[i] == "..":
            remove parts[i]
            if i > 0: remove parts[i - 1]   (".." cancels the name before it; none at the root)
            changed = true
            break
return "/" + parts joined by "/"

simplify_path.optimal:
stack = empty stack of directory names
for each part in path split on "/":
    if part == "..":
        if the stack is not empty: pop the top   (go up one level; no-op at the root)
    else if part is not "" and not ".":
        push part   ("" from // and "." are skipped)
return "/" + stack joined by "/"

minimum_remove_to_make_valid_parentheses.optimal:
chars = list of the characters of s
stack = empty stack of indices of "(" not yet closed
for each index i in s:
    if s[i] == "(":
        push i
    else if s[i] == ")":
        if the stack is not empty: pop the top   (pair it with the most recent open "(")
        else: chars[i] = ""   (unmatched ")": delete)
for each index i still on the stack:
    chars[i] = ""   ("(" never closed: delete)
return chars joined

longest_palindromic_substring.brute:
best = ""
for each start i:
    for each end j >= i:
        sub = s[i..j]
        if length of sub > length of best and sub reads the same reversed:
            best = sub   (longer and a palindrome: new best)
return best

longest_palindromic_substring.optimal:
expand(s, lo, hi):
    while lo >= 0 and hi < n and s[lo] == s[hi]:
        lo -= 1, hi += 1   (grow outward while both ends match)
    return (lo + 1, hi - lo - 1)   (the loop overshoots by one on each side)
best_start = 0, best_len = 0
for each index i:
    start, length = expand(s, i, i)   (odd length, centred on s[i])
    if length > best_len: best_start = start, best_len = length
    start, length = expand(s, i, i + 1)   (even length, centred between s[i] and s[i+1])
    if length > best_len: best_start = start, best_len = length
return s[best_start .. best_start + best_len)

design_hashmap.brute:
init:
    pairs = empty list of [key, value]
put(key, value):
    for each pair in pairs:
        if pair.key == key: pair.value = value, return   (overwrite in place)
    append [key, value] to pairs
get(key):
    for each pair in pairs:
        if pair.key == key: return pair.value
    return -1
remove(key):
    for each index i in pairs:
        if pairs[i].key == key: remove pairs[i], return
